<?php use VazinCMS\Security;$labels=['new'=>'جدید','awaiting_payment'=>'منتظر پرداخت','paid'=>'پرداخت‌شده','reviewing'=>'در حال بررسی','documents_required'=>'نیازمند مدرک','processing'=>'در حال انجام','completed'=>'تکمیل‌شده','rejected'=>'ردشده','cancelled'=>'لغوشده']; ?>
<section class="title"><div><span class="eyebrow">مدیریت عملیات</span><h1>پرونده‌های ویزا</h1><p>دریافت فرم، مدارک و بررسی دستی برای tenant وایت‌لیبل.</p></div><a class="button secondary" href="/fa/visa" target="_blank">نمایش فرم دستی</a></section>
<section class="grid stats"><article><b><?=(int)($stats['total']??0)?></b><span>کل پرونده‌ها</span></article><article><b><?=(int)($stats['open']??0)?></b><span>نیازمند اقدام</span></article><article><b><?=(int)($stats['docs']??0)?></b><span>منتظر مدرک</span></article><article><b><?=(int)($stats['manual']??0)?></b><span>بررسی دستی</span></article></section>
<section class="panel"><form class="filters" method="get"><label>جستجو<input name="q" value="<?=Security::e($q)?>" placeholder="کد پرونده، نام یا تلفن"></label><label>وضعیت<select name="status"><option value="">همه وضعیت‌ها</option><?php foreach($labels as$v=>$l):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><button>اعمال فیلتر</button></form><div class="table"><table><thead><tr><th>پرونده</th><th>متقاضی</th><th>خدمت</th><th>مدل انجام</th><th>مدارک</th><th>وضعیت</th></tr></thead><tbody><?php foreach($orders as$o):?><tr><?php $manual=(($o['payment_status']??'')==='not_required'||(float)($o['amount']??0)===0.0);?><td><a href="/admin/visa-orders/<?=(int)$o['id']?>"><strong><?=Security::e($o['public_id'])?></strong></a><br><small><?=Security::e((string)$o['created_at'])?></small></td><td><?=Security::e($o['full_name'])?><br><small dir="ltr"><?=Security::e($o['phone'])?></small></td><td><?=Security::e((string)($o['product_title']?:$o['service_type']))?></td><td><span class="status <?=$manual?'active':'suspended'?>"><?=$manual?'بررسی دستی، بدون پرداخت':'رکورد legacy'?></span></td><td><?=(int)$o['document_count']?> فایل</td><td><span class="status <?=Security::e($o['status'])?>"><?=Security::e($labels[$o['status']]??$o['status'])?></span></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="6">پرونده‌ای مطابق فیلتر پیدا نشد.</td></tr><?php endif;?></tbody></table></div></section>
